
CREATE DATABASE IF NOT EXISTS hospital_management CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE hospital_management;

SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS prescription_medicines;

DROP TABLE IF EXISTS prescriptions;

DROP TABLE IF EXISTS alerts;

DROP TABLE IF EXISTS vital_signs;

DROP TABLE IF EXISTS medical_records;

DROP TABLE IF EXISTS admissions;

DROP TABLE IF EXISTS appointments;

DROP TABLE IF EXISTS patients;

DROP TABLE IF EXISTS doctors;

DROP TABLE IF EXISTS medicines;

DROP TABLE IF EXISTS departments;

SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE departments (
 department_id INT AUTO_INCREMENT PRIMARY KEY,
 department_name VARCHAR(100) NOT NULL UNIQUE,
 location VARCHAR(100),
 contact_number VARCHAR(15)
) ENGINE=InnoDB;

CREATE TABLE doctors (
 doctor_id INT AUTO_INCREMENT PRIMARY KEY,
 first_name VARCHAR(50) NOT NULL,
 last_name VARCHAR(50) NOT NULL,
 specialization VARCHAR(100) NOT NULL,
 qualification VARCHAR(100),
 department_id INT NOT NULL,
 phone VARCHAR(15),
 email VARCHAR(100) UNIQUE,
 CONSTRAINT fk_doctors_department FOREIGN KEY (department_id) REFERENCES departments(department_id)
) ENGINE=InnoDB;

CREATE TABLE patients (
 patient_id INT AUTO_INCREMENT PRIMARY KEY,
 first_name VARCHAR(50) NOT NULL,
 last_name VARCHAR(50) NOT NULL,
 date_of_birth DATE NOT NULL,
 gender ENUM('Female','Male','Other') NOT NULL,
 blood_group VARCHAR(5),
 phone VARCHAR(15) NOT NULL,
 email VARCHAR(100),
 address VARCHAR(255),
 emergency_contact_name VARCHAR(100),
 emergency_contact_phone VARCHAR(15),
 registration_date DATE NOT NULL DEFAULT (CURRENT_DATE)
) ENGINE=InnoDB;

CREATE TABLE appointments (
 appointment_id INT AUTO_INCREMENT PRIMARY KEY,
 patient_id INT NOT NULL,
 doctor_id INT NOT NULL,
 appointment_date DATE NOT NULL,
 appointment_time TIME NOT NULL,
 status ENUM('Scheduled','Completed','Cancelled','No-show') DEFAULT 'Scheduled',
 reason VARCHAR(255),
 CONSTRAINT fk_appointments_patient FOREIGN KEY (patient_id) REFERENCES patients(patient_id),
 CONSTRAINT fk_appointments_doctor FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id),
 INDEX idx_appointments_date (appointment_date),
 INDEX idx_appointments_patient (patient_id)
) ENGINE=InnoDB;

CREATE TABLE admissions (
 admission_id INT AUTO_INCREMENT PRIMARY KEY,
 patient_id INT NOT NULL,
 department_id INT NOT NULL,
 admitting_doctor_id INT NOT NULL,
 bed_number VARCHAR(10) NOT NULL,
 admission_date DATETIME DEFAULT CURRENT_TIMESTAMP,
 discharge_date DATETIME NULL,
 status ENUM('Admitted','Discharged','Transferred') DEFAULT 'Admitted',
 CONSTRAINT fk_admissions_patient FOREIGN KEY (patient_id) REFERENCES patients(patient_id),
 CONSTRAINT fk_admissions_department FOREIGN KEY (department_id) REFERENCES departments(department_id),
 CONSTRAINT fk_admissions_doctor FOREIGN KEY (admitting_doctor_id) REFERENCES doctors(doctor_id),
 CHECK (discharge_date IS NULL OR discharge_date >= admission_date),
 INDEX idx_admissions_dates (admission_date, discharge_date)
) ENGINE=InnoDB;

CREATE TABLE medical_records (
 record_id INT AUTO_INCREMENT PRIMARY KEY,
 patient_id INT NOT NULL,
 doctor_id INT NOT NULL,
 visit_date DATETIME DEFAULT CURRENT_TIMESTAMP,
 chief_complaint VARCHAR(255),
 notes TEXT,
 CONSTRAINT fk_records_patient FOREIGN KEY (patient_id) REFERENCES patients(patient_id),
 CONSTRAINT fk_records_doctor FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id),
 INDEX idx_records_visit_date (visit_date)
) ENGINE=InnoDB;

CREATE TABLE vital_signs (
 vital_id INT AUTO_INCREMENT PRIMARY KEY,
 admission_id INT NOT NULL,
 recorded_at DATETIME DEFAULT CURRENT_TIMESTAMP,
 heart_rate SMALLINT,
 systolic_bp SMALLINT,
 diastolic_bp SMALLINT,
 temperature DECIMAL(4,1),
 respiratory_rate SMALLINT,
 spo2 SMALLINT,
 CONSTRAINT fk_vitals_admission FOREIGN KEY (admission_id) REFERENCES admissions(admission_id),
 CHECK (heart_rate IS NULL OR heart_rate BETWEEN 20 AND 250),
 CHECK (spo2 IS NULL OR spo2 BETWEEN 0 AND 100),
 INDEX idx_vitals_recorded_at (recorded_at)
) ENGINE=InnoDB;

CREATE TABLE alerts (
 alert_id INT AUTO_INCREMENT PRIMARY KEY,
 vital_id INT NOT NULL,
 alert_type VARCHAR(50) NOT NULL,
 severity ENUM('Low','Medium','High','Critical') NOT NULL,
 generated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
 acknowledged_at DATETIME NULL,
 CONSTRAINT fk_alerts_vital FOREIGN KEY (vital_id) REFERENCES vital_signs(vital_id),
 INDEX idx_alerts_severity (severity)
) ENGINE=InnoDB;

CREATE TABLE prescriptions (
 prescription_id INT AUTO_INCREMENT PRIMARY KEY,
 record_id INT NOT NULL,
 doctor_id INT NOT NULL,
 prescription_date DATE DEFAULT (CURRENT_DATE),
 CONSTRAINT fk_prescriptions_record FOREIGN KEY (record_id) REFERENCES medical_records(record_id),
 CONSTRAINT fk_prescriptions_doctor FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id)
) ENGINE=InnoDB;

CREATE TABLE medicines (
 medicine_id INT AUTO_INCREMENT PRIMARY KEY,
 medicine_name VARCHAR(100) NOT NULL,
 manufacturer VARCHAR(100),
 unit_price DECIMAL(10,2) NOT NULL DEFAULT 0.00,
 stock_quantity INT NOT NULL DEFAULT 0,
 CHECK (unit_price >= 0),
 CHECK (stock_quantity >= 0)
) ENGINE=InnoDB;

CREATE TABLE prescription_medicines (
 prescription_id INT NOT NULL,
 medicine_id INT NOT NULL,
 dosage VARCHAR(50) NOT NULL,
 frequency VARCHAR(50) NOT NULL,
 duration_days SMALLINT NOT NULL,
 PRIMARY KEY (prescription_id, medicine_id),
 CONSTRAINT fk_pm_prescription FOREIGN KEY (prescription_id) REFERENCES prescriptions(prescription_id),
 CONSTRAINT fk_pm_medicine FOREIGN KEY (medicine_id) REFERENCES medicines(medicine_id),
 CHECK (duration_days > 0)
) ENGINE=InnoDB;

