CREATE OR REPLACE VIEW vw_patient_appointment_summary AS
SELECT p.patient_id, CONCAT(p.first_name,' ',p.last_name) AS patient_name,
       COUNT(a.appointment_id) AS total_appointments,
       SUM(a.status='Completed') AS completed_appointments
FROM patients p LEFT JOIN appointments a ON a.patient_id=p.patient_id
GROUP BY p.patient_id, p.first_name, p.last_name;

CREATE OR REPLACE VIEW vw_abnormal_vitals AS
SELECT v.vital_id, v.admission_id, v.recorded_at, v.heart_rate, v.systolic_bp,
       v.diastolic_bp, v.temperature, v.spo2
FROM vital_signs v
WHERE v.heart_rate < 50 OR v.heart_rate > 120
   OR v.systolic_bp < 90 OR v.systolic_bp > 160
   OR v.diastolic_bp < 60 OR v.diastolic_bp > 100
   OR v.temperature >= 38.0 OR v.spo2 < 92;

DELIMITER //

CREATE TRIGGER trg_vital_sign_alert AFTER INSERT ON vital_signs
FOR EACH ROW
BEGIN
 IF NEW.heart_rate < 50 OR NEW.heart_rate > 120 THEN
   INSERT INTO alerts(vital_id, alert_type, severity) VALUES(NEW.vital_id, 'Abnormal heart rate', 'High');
 ELSEIF NEW.spo2 < 92 THEN
   INSERT INTO alerts(vital_id, alert_type, severity) VALUES(NEW.vital_id, 'Low oxygen saturation', 'High');
 ELSEIF NEW.temperature >= 38.0 THEN
   INSERT INTO alerts(vital_id, alert_type, severity) VALUES(NEW.vital_id, 'High temperature', 'Medium');
 END IF;
END//

CREATE PROCEDURE sp_patient_appointments(IN p_patient_id INT)
BEGIN
 SELECT a.appointment_id, a.appointment_date, a.appointment_time, a.status,
        a.reason, CONCAT(d.first_name,' ',d.last_name) AS doctor_name
 FROM appointments a JOIN doctors d ON a.doctor_id=d.doctor_id
 WHERE a.patient_id=p_patient_id
 ORDER BY a.appointment_date DESC, a.appointment_time DESC;
END//


